//! The parameter dictionary's table (L044, L046, L058). Generated by ecosystem/tools/build.py from
//! ecosystem/data/parameters.yml: do not edit by hand. The theory of each parameter is on the manual page
//! "Parameters: the theory"; the test `parameter_dictionary` checks this table against the core's fields.

/// One entry of the dictionary: every field of `parameters.yml` (strings; LaTeX in `symbol` and `equation`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Parameter {
    pub id: &'static str,
    /// The display name.
    pub name: &'static str,
    /// A key of `GROUPS`.
    pub group: &'static str,
    /// "parameter" (refinable) or "control".
    pub kind: &'static str,
    /// LaTeX.
    pub symbol: &'static str,
    pub unit: &'static str,
    pub refinable: bool,
    pub meaning: &'static str,
    /// LaTeX.
    pub equation: &'static str,
    /// The paper behind the equation, as a reference; empty if none.
    pub paper: &'static str,
    /// Where the equation is printed (M: FullProf's material, P: the papers, G: GSAS-II's code).
    pub eq_src: &'static [&'static str],
    pub fullprof: &'static str,
    pub gsas2: &'static str,
    /// Measured on the FullProf material (L046).
    pub range: &'static str,
    pub default: &'static str,
    /// When to refine it.
    pub refine: &'static str,
    /// The bounds the engine holds it within (P39), in words; empty for a control.
    pub limits: &'static str,
    /// FullProf's relaxation class (atomic, anisotropic, profile, global: `steering::Class`); empty for a control.
    pub class: &'static str,
    /// Where the class is stated (the manual's LINE 9), or why it is believed.
    pub class_source: &'static str,
    /// The largest shift per cycle the engine allows by default, in `unit` (a number), or "none"; empty for a control.
    pub max_shift: &'static str,
    /// Where FullProf departs from the paper and how a .pcr is translated; empty if nothing.
    pub note: &'static str,
    /// The parameters it is correlated with in a refinement, and why (R24, L076).
    pub correlations: &'static [Correlation],
    /// The core's fields that hold it (`Struct.field`).
    pub core: &'static [&'static str],
}

/// A correlation of the dictionary: the parameters, why (from the equations and the paper), what to do, where it
/// is written (M: FullProf's material, P: the papers).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Correlation {
    pub with: &'static [&'static str],
    pub why: &'static str,
    pub tip: &'static str,
    pub source: &'static [&'static str],
}

/// The groups of the dictionary: (key, title), in order.
pub const GROUPS: &[(&str, &str)] = &[
    ("radiation", "Radiation and instrument"),
    ("position", "Peak positions"),
    ("width", "Peak widths and shape"),
    ("asymmetry", "Peak asymmetry"),
    ("intensity", "Intensity corrections"),
    ("background", "Background"),
    ("structure", "Phase and structure"),
    ("calculation", "Calculation controls"),
];

